package com.findit.model;

import java.time.LocalDateTime;

/**
 * Model class representing a potential match between a LOST and a FOUND item.
 * Generated by the MatchingService algorithm.
 */
public class MatchSuggestion {

    private int          matchId;
    private int          lostItemId;
    private int          foundItemId;
    private String       lostItemTitle;   // Joined for display
    private String       foundItemTitle;  // Joined for display
    private int          matchScore;      // 0–100 similarity score
    private String       matchingReasons; // Human-readable explanation
    private MatchStatus  status;
    private LocalDateTime createdAt;

    public enum MatchStatus {
        SUGGESTED, DISMISSED, CONFIRMED
    }

    public MatchSuggestion() {}

    public MatchSuggestion(int lostItemId, int foundItemId, int matchScore, String matchingReasons) {
        this.lostItemId      = lostItemId;
        this.foundItemId     = foundItemId;
        this.matchScore      = matchScore;
        this.matchingReasons = matchingReasons;
        this.status          = MatchStatus.SUGGESTED;
    }

    // ── Getters & Setters ─────────────────────────────────────────────────

    public int    getMatchId()          { return matchId; }
    public void   setMatchId(int id)    { this.matchId = id; }

    public int    getLostItemId()            { return lostItemId; }
    public void   setLostItemId(int id)      { this.lostItemId = id; }

    public int    getFoundItemId()           { return foundItemId; }
    public void   setFoundItemId(int id)     { this.foundItemId = id; }

    public String getLostItemTitle()                  { return lostItemTitle; }
    public void   setLostItemTitle(String t)          { this.lostItemTitle = t; }

    public String getFoundItemTitle()                 { return foundItemTitle; }
    public void   setFoundItemTitle(String t)         { this.foundItemTitle = t; }

    public int    getMatchScore()             { return matchScore; }
    public void   setMatchScore(int s)        { this.matchScore = s; }

    public String getMatchingReasons()                    { return matchingReasons; }
    public void   setMatchingReasons(String r)            { this.matchingReasons = r; }

    public MatchStatus getStatus()              { return status; }
    public void        setStatus(MatchStatus s) { this.status = s; }

    public LocalDateTime getCreatedAt()                { return createdAt; }
    public void          setCreatedAt(LocalDateTime t) { this.createdAt = t; }

    /** Human-readable quality label for the match score */
    public String getScoreLabel() {
        if (matchScore >= 80) return "Excellent Match";
        if (matchScore >= 60) return "Good Match";
        if (matchScore >= 40) return "Possible Match";
        return "Weak Match";
    }
}
